/**
 * Generate the Think agent composition from each agent package's `dshBase.agent`
 * metadata. The app keeps no hand-written agent roster.
 */
import { writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { readAgentRows } from "./packs.mjs";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const output = join(repoRoot, "apps", "web", "src", "agent", "generated-composition.ts");
const rows = readAgentRows(repoRoot);
const lines = [
  "/* Generated by scripts/composition/generate-agent-composition.mjs; do not edit. */",
  'import type { DshPlugin } from "@dsh-base/cloudflare-think-core";',
  'import type { Env } from "../env";',
  ...rows.map((row, index) => `import { ${row.export} as plugin${index} } from ${JSON.stringify(row.module)};`),
  "",
  "export const agentPlugins: readonly DshPlugin<Env>[] = [",
  ...rows.map((row, index) => `  plugin${index} as unknown as DshPlugin<Env>, // ${row.id}`),
  "];",
  "",
];
writeFileSync(output, lines.join("\n"));
console.log(`agent composition: ${rows.length} entries → ${output}`);
